  public static void s1Bad(int x) { if(x < 0 || x > 999) return; String r = String.format("%05d", x); assert r.startsWith("000"); }
  public static void s2(int x) { String r = String.format("%+d", x); assert r.charAt(0) == '+' || r.charAt(0) == '-'; }
  public static void s3(int x) { if(x >= 0) return; String r = String.format("%(d", x); assert r.charAt(0) == '(' && r.charAt(r.length() - 1) == ')'; }
  public static void s4(String s) { if(s == null || s.length() > 3) return; String r = String.format("[%-5s]", s); assert r.length() == 7 && r.charAt(6) == ']' && r.charAt(5) == ' '; }
  public static void s5(String s) { if(s == null) return; String r = String.format("%.2s", s); assert r.length() <= 2; }
  public static void s5Bad(String s) { if(s == null) return; String r = String.format("%.2s", s); assert r.length() < 2; }
  public static void s6(int x) { String r = String.format("%#x", x); assert r.startsWith("0x"); }
  public static void s7(double d) { if(d != d) return; String r = String.format("%10.2f", d); assert r.length() >= 10; }
